.earth-diagram {
  position: relative;
  width: 380px;
  height: 380px;
  margin: 0 auto;
  border-radius: 50%;
  background: radial-gradient(circle,
    #ffd700 0%,
    #ffd700 15%,
    #ff8c00 15%,
    #ff8c00 35%,
    #c0392b 35%,
    #a0522d 55%,
    #8b4513 55%,
    #6b8e23 72%,
    #4682b4 72%,
    #4682b4 75%,
    #1a5276 75%
  );
  box-shadow:
    0 0 60px rgba(255, 140, 0, 0.3),
    0 0 120px rgba(255, 100, 0, 0.1),
    inset 0 0 30px rgba(0,0,0,0.3);
}

.earth-diagram .label {
  position: absolute;
  font-size: 0.75rem;
  font-weight: bold;
  color: #fff;
  text-shadow: 0 1px 3px rgba(0,0,0,0.8);
  white-space: nowrap;
}

.label-inner-core { top: 50%; left: 50%; transform: translate(-50%, -50%); }
.label-outer-core { top: 28%; left: 50%; transform: translateX(-50%); }
.label-mantle { top: 15%; left: 50%; transform: translateX(-50%); }
.label-crust { top: 5%; left: 50%; transform: translateX(-50%); color: #87ceeb; }
.label-atmosphere { top: -10%; left: 50%; transform: translateX(-50%); color: #87ceeb; font-size: 0.7rem; }

/* Layer info cards */
.layers-info {
  display: flex;
  flex-direction: column;
  gap: 1.5rem;
}

.layer-card {
  background: rgba(255, 255, 255, 0.05);
  border-radius: 12px;
  padding: 1.5rem;
  border-right: 4px solid;
