  align-items: center;
  gap: 0.5rem;
}

.layer-card p {
  font-size: 0.9rem;
  color: #c8d8e8;
  margin-bottom: 0.4rem;
}

.layer-card .stats {
  display: flex;
  gap: 1rem;
  margin-top: 0.8rem;
