            if (board[7][4] == 'K' and board[7][0] == 'R'
                    and board[7][3] is None and board[7][2] is None and board[7][1] is None
                    and not _is_attacked(board, 7, 4, opp)
                    and not _is_attacked(board, 7, 3, opp)
                    and not _is_attacked(board, 7, 2, opp)):
                moves.append('e1c1')
    else:
        opp = 'w'
        if 'k' in castling:
            if (board[0][4] == 'k' and board[0][7] == 'r'
                    and board[0][5] is None and board[0][6] is None
                    and not _is_attacked(board, 0, 4, opp)
                    and not _is_attacked(board, 0, 5, opp)
                    and not _is_attacked(board, 0, 6, opp)):
                moves.append('e8g8')
        if 'q' in castling:
